/**
 * @file pal_wifi_ap_esp.c
 * @brief PAL WiFi AP - ESP-IDF Backend
 *
 * Wraps esp_wifi in AP mode for captive portal / provisioning.
 * Auto-generated by embedOS.
 */

#include "pal_wifi_ap.h"

#include <string.h>
#include "esp_wifi.h"
#include "esp_event.h"
#include "esp_netif.h"
#include "esp_log.h"

static const char *TAG = "pal_wifi_ap";

static esp_netif_t *s_ap_netif = NULL;
static bool s_ap_active = false;
static int s_client_count = 0;
static pal_wifi_ap_callback_t s_callback = NULL;
static void *s_callback_data = NULL;

static void ap_event_handler(void *arg, esp_event_base_t base,
                             int32_t id, void *event_data) {
    if (id == WIFI_EVENT_AP_STACONNECTED) {
        s_client_count++;
        if (s_callback) s_callback(PAL_WIFI_AP_EVENT_CLIENT_CONNECTED, s_callback_data);
        ESP_LOGI(TAG, "Client connected (total: %d)", s_client_count);
    } else if (id == WIFI_EVENT_AP_STADISCONNECTED) {
        if (s_client_count > 0) s_client_count--;
        if (s_callback) s_callback(PAL_WIFI_AP_EVENT_CLIENT_DISCONNECTED, s_callback_data);
        ESP_LOGI(TAG, "Client disconnected (total: %d)", s_client_count);
    }
}

int pal_wifi_ap_start(const pal_wifi_ap_config_t *config) {
    if (!config || !config->ssid) return -1;
    if (s_ap_active) return 0;

    esp_netif_init();
    esp_event_loop_create_default();

    if (!s_ap_netif) {
        s_ap_netif = esp_netif_create_default_wifi_ap();
    }

    wifi_init_config_t cfg = WIFI_INIT_CONFIG_DEFAULT();
    esp_wifi_init(&cfg);

    esp_event_handler_instance_register(WIFI_EVENT, ESP_EVENT_ANY_ID,
                                        &ap_event_handler, NULL, NULL);

    wifi_config_t wifi_cfg = {0};
    strncpy((char *)wifi_cfg.ap.ssid, config->ssid, sizeof(wifi_cfg.ap.ssid) - 1);
    wifi_cfg.ap.ssid_len = strlen(config->ssid);
    wifi_cfg.ap.channel = config->channel ? config->channel : 6;
    wifi_cfg.ap.max_connection = config->max_connections ? config->max_connections : 4;

    if (config->password && strlen(config->password) >= 8) {
        strncpy((char *)wifi_cfg.ap.password, config->password, sizeof(wifi_cfg.ap.password) - 1);
        wifi_cfg.ap.authmode = WIFI_AUTH_WPA2_PSK;
    } else {
        wifi_cfg.ap.authmode = WIFI_AUTH_OPEN;
    }

    esp_wifi_set_mode(WIFI_MODE_AP);
    esp_wifi_set_config(WIFI_IF_AP, &wifi_cfg);
    esp_wifi_start();

    s_ap_active = true;
    s_client_count = 0;
    ESP_LOGI(TAG, "AP started: %s", config->ssid);
    return 0;
}

int pal_wifi_ap_stop(void) {
    if (!s_ap_active) return 0;
    esp_wifi_stop();
    s_ap_active = false;
    s_client_count = 0;
    ESP_LOGI(TAG, "AP stopped");
    return 0;
}

bool pal_wifi_ap_is_active(void) {
    return s_ap_active;
}

int pal_wifi_ap_get_client_count(void) {
    return s_client_count;
}

int pal_wifi_ap_get_ip(char *buf, size_t buf_len) {
    if (!buf || buf_len < 16) return -1;
    if (!s_ap_netif) return -2;

    esp_netif_ip_info_t ip_info;
    if (esp_netif_get_ip_info(s_ap_netif, &ip_info) != ESP_OK) return -3;

    snprintf(buf, buf_len, IPSTR, IP2STR(&ip_info.ip));
    return 0;
}

void pal_wifi_ap_set_callback(pal_wifi_ap_callback_t cb, void *user_data) {
    s_callback = cb;
    s_callback_data = user_data;
}